":"Trang cửa hàng đăng sản phẩm về cửa hàng ngày 11/11/2026, địa chỉ Lầu 1 35 Nguyễn Văn Tráng; ELLE xác nhận chuyên VPP và cửa hàng tại đây. Phường Bến Thành đối chiếu địa giới 2025.","legacy":"Lầu 1, 35 Nguyễn Văn Tráng, phường Bến Thành cũ, Quận 1","address_line":"Lầu 1, 35 Nguyễn Văn Tráng, phường Bến Thành, TP. Hồ Chí Minh","address_legacy":"Lầu 1, 35 Nguyễn Văn Tráng, phường Bến Thành cũ, Quận 1, TP.HCM cũ","verification_note":"Trang cửa hàng đăng sản phẩm về cửa hàng ngày 11/11/2026, địa chỉ Lầu 1 35 Nguyễn Văn Tráng; ELLE xác nhận chuyên VPP và cửa hàng tại đây. Phường Bến Thành đối chiếu địa giới 2025.","google_maps_url":null,"google_place_id":null}]'::jsonb) x (
    ward_new text,name text,street text,category text,phone text,
    source_key text,source_url text,detail text,legacy text,
    address_line text,address_legacy text,verification_note text,
    google_maps_url text,google_place_id text
  )
), checked AS (
  SELECT * FROM src s
  WHERE s.ward_new IN ('Sài Gòn','Tân Định','Bến Thành')
    AND s.category IN ('nha_sach','van_phong_pham')
    AND s.source_url LIKE 'https://%'
    AND s.address_line ILIKE '%phường '||s.ward_new||'%'
    AND length(s.name)>=2 AND length(s.address_line)>=3
    AND NOT EXISTS (
      SELECT 1 FROM public.customers c
      WHERE c.province='TP Hồ Chí Minh'
        AND (lower(trim(c.name))=lower(trim(s.name))
          OR (s.phone IS NOT NULL AND regexp_replace(coalesce(c.phone,''),'[^0-9]','','g')=s.phone AND c.phone IS NOT NULL)
          OR (lower(trim(c.address_line))=lower(trim(s.address_line))))
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.field_prospects p
      WHERE p.research_source_key=s.source_key
        OR (p.province='TP Hồ Chí Minh' AND (
             (lower(trim(p.name))=lower(trim(s.name)) AND p.district='Quận 1')
             OR lower(trim(p.address_line))=lower(trim(s.address_line))
             OR (s.phone IS NOT NULL AND regexp_replace(coalesce(p.phone,''),'[^0-9]','','g')=s.phone AND p.phone IS NOT NULL)
             OR (s.google_place_id IS NOT NULL AND p.google_place_id=s.google_place_id)
        ))
    )
), inserted AS (
  INSERT INTO public.field_prospects(
    id,area_visit_id,owner_sub,name,address_line,province,district,ward_new,
    address_legacy,category,phone,tax_code,note,status,source_kind,
    research_source_key,research_source_url,research_batch,google_maps_url,google_place_id)
  SELECT gen_random_uuid(),NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,
    s.address_line,'TP Hồ Chí Minh','Quận 1',s.ward_new,s.address_legacy,
    s.category,s.phone,NULL,
    'Nghiên cứu công khai 22/11/2026; CHƯA GHÉ; chưa xác minh GPS, giờ mở cửa, trạng thái bán hàng tại chỗ. '||
    s.verification_note||' Nguồn: '||s.source_url,
    'new','manual',s.source_key,s.source_url,
    '2026-11-22-hcm-old-sg-tandinh-benthanh-164',s.google_maps_url,s.google_place_id
  FROM checked s
  ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
  RETURNING ward_new,name,category,phone
)
SELECT ward_new,name,category,phone FROM inserted ORDER BY ward_new,name;
